using namespace ark;using V=arkjson::Value;
static void check(bool pass,const char* message){if(!pass)throw std::runtime_error(message);}
static V parse(const char* text){V v;check(arkjson::parse(text,v),"fixture JSON");return v;}
static V query(AgentSession& s,const char* tool,V args){auto out=s.call(tool,args);if(out.find("isError")->b)throw std::runtime_error(out.dump());return *out.find("structuredContent");}
static V write(AgentSession& s,const char* commands){V args=V::makeObj();args.set("expected_revision",V::makeNum((double)s.revision));args.set("commands",parse(commands));return s.call("doc_apply",args);}
static void apply(AgentSession& s,const char* commands){auto out=write(s,commands);if(out.find("isError")->b)throw std::runtime_error(out.dump());}
static V inspect(AgentSession& s,u64 id){V args=V::makeObj();args.set("id",V::makeNum((double)id));return query(s,"native_inspect",args);}
static double volume(AgentSession& s,u64 id){return inspect(s,id).find("report")->find("volume_mm3")->num;}
static void rejection(AgentSession& s,const char* commands,const char* reason){const auto before=documentToJson(s.document,false,false);const auto revision=s.revision;const auto out=write(s,commands);check(out.find("isError")->b,"invalid hole must reject");if(out.dump().find(reason)==std::string::npos)throw std::runtime_error(std::string("Expected rejection ")+reason+" / "+out.dump());check(s.revision==revision&&documentToJson(s.document,false,false)==before,"rejected hole must preserve document and revision");}
